#include <bits/stdc++.h>using namespace std;#define int long long#define go(i,a,b) for(int i=a;i<=b;i++)#define og(i,a,b) for(int i=b;i>=a;i--)#define all() a.begin() + 1,a.begin() + n + 1 int T,n,k;vector<int> a,b,c,ans; void dfs(int x){    int p = b[x];    if(p == k + 1) return;    if(p < k && c[p + 1] == a[p + 1]){        int y = 0;        go(i,1,n){            if(b[i] == p + 1){                y = i;                break;            }        }        dfs(y);    }    c[p]--;    b[x]++;    c[b[x]]++;    ans.push_back(x);} void O_o(){    cin >> n >> k;    a.assign(k + 2, 0);    b.assign(n + 1, 0);    c.assign(k + 2, 0);    ans.clear();     go(i,1,k) cin >> a[i];    go(i,1,n){        cin >> b[i];        c[b[i]]++;    }     go(i,1,n){        while(b[i] <= k) dfs(i);    }     cout << ans.size() << '\n';    for(auto x : ans) cout << x << ' ';    cout << '\n';} signed main(){    ios::sync_with_stdio(false);    cin.tie(nullptr);    cout.tie(nullptr);    cin >> T;    while(T--) O_o();}